// Puts the guide for Claude (claude/guide/*.md) into the helper program:
// writes lib/mcp/guide_content.dart, which the `get_guide` tool serves.
//
//   dart run tool/gen_guide.dart          (from video-editor/)
//
// Run it after changing a file in claude/guide/. A test
// (test/mcp/claude_guides_test.dart) fails when the generated file is out
// of date. Uses only dart:io.

import 'dart:io';

/// The sections, in the order `get_guide` lists them: name -> one line.
const Map<String, String> kGuideSectionSummaries = {
  'start': 'Who you are helping, the workflow, the safety rules, what you '
      'can and cannot know. Read first.',
  'recipes': 'Step-by-step for the usual jobs (podcast, music, montage, '
      'sport, upright, shorts, captions, fillers, sound only).',
  'tools': 'Every tool with its arguments and the rules that are easy to '
      'get wrong.',
  'troubleshooting': 'What to do when something does not work.',
};

/// The text of lib/mcp/guide_content.dart for the guide in [guideDir].
String generateGuideDart(String guideDir) {
  final out = StringBuffer()
    ..writeln('// GENERATED by tool/gen_guide.dart from claude/guide/*.md.')
    ..writeln('// Do not edit: change the .md file and run')
    ..writeln('//   dart run tool/gen_guide.dart')
    ..writeln()
    ..writeln('/// Section name -> what it is for (one line).')
    ..writeln('const Map<String, String> kGuideSummaries = {');
  for (final e in kGuideSectionSummaries.entries) {
    out.writeln("  '${e.key}': '${e.value.replaceAll("'", r"\'")}',");
  }
  out
    ..writeln('};')
    ..writeln()
    ..writeln('/// Section name -> its text (Markdown).')
    ..writeln('const Map<String, String> kGuideSections = {');
  for (final name in kGuideSectionSummaries.keys) {
    final file = File('$guideDir/$name.md');
    if (!file.existsSync()) {
      throw StateError('missing guide section: ${file.path}');
    }
    final text = file.readAsStringSync().replaceAll('\r\n', '\n').trimRight();
    if (text.contains("'''")) {
      throw StateError("${file.path} contains ''' (not allowed)");
    }
    out.writeln("  '$name': r'''");
    out.writeln(text);
    out.writeln("''',");
  }
  out.writeln('};');
  return out.toString();
}

void main(List<String> args) {
  final root = File('pubspec.yaml').existsSync() ? '.' : 'video-editor';
  final text = generateGuideDart('$root/claude/guide');
  final target = File('$root/lib/mcp/guide_content.dart');
  if (args.contains('--check')) {
    if (!target.existsSync() || target.readAsStringSync() != text) {
      stderr.writeln('lib/mcp/guide_content.dart is out of date: run '
          'dart run tool/gen_guide.dart');
      exit(1);
    }
    return;
  }
  target.writeAsStringSync(text);
  stdout.writeln('wrote ${target.path} (${text.length} characters)');
}
